package codegen

import (
	"os"
	"strings"
	"testing"
)

// Constants and FrontendFS are generated into go/app (package app), so a
// test binary that imports the app package gets them (EXTEND.md › App
// Wiring). The old generated files in go/ are removed.
func TestConstantsAndFrontendGoToApp(t *testing.T) {
	t.Chdir(t.TempDir())
	writeMinimalProject(t)
	writeFiles(t, map[string]string{
		"frontend/package.json":     "{}",
		"go/constants.gen.go":       "// Code generated by schemaf codegen. DO NOT EDIT.\npackage main\n",
		"go/frontend.gen.go":        "// Code generated by schemaf codegen. DO NOT EDIT.\npackage main\n",
		"go/frontend_dist/.gitkeep": "",
	})
	if err := runConstantsGen(); err != nil {
		t.Fatal(err)
	}
	if err := runFrontendGen(); err != nil {
		t.Fatal(err)
	}

	for path, want := range map[string]string{
		"go/app/constants.gen.go": "package app",
		"go/app/frontend.gen.go":  "package app",
	} {
		if got := readFile(t, path); !strings.Contains(got, want) {
			t.Errorf("%s lacks %q:\n%s", path, want, got)
		}
	}
	if !strings.Contains(readFile(t, "go/app/constants.gen.go"), `constants.SetProjectName("myapp")`) {
		t.Error("constants.gen.go doesn't set the project name")
	}
	if _, err := os.Stat("go/app/frontend_dist/.gitkeep"); err != nil {
		t.Errorf("go/app/frontend_dist/.gitkeep: %v", err)
	}
	for _, gone := range []string{"go/constants.gen.go", "go/frontend.gen.go", "go/frontend_dist"} {
		if _, err := os.Stat(gone); !os.IsNotExist(err) {
			t.Errorf("%s survives codegen (err %v)", gone, err)
		}
	}
}

// A hand-written file at an old path is never touched.
func TestOldPathsKeepHandWrittenFiles(t *testing.T) {
	t.Chdir(t.TempDir())
	writeMinimalProject(t)
	writeFiles(t, map[string]string{
		"go/constants.gen.go":        "package main\n// mine\n",
		"go/frontend_dist/notes.txt": "mine",
	})
	if err := runConstantsGen(); err != nil {
		t.Fatal(err)
	}
	if err := removeLegacyAppFiles(); err != nil {
		t.Fatal(err)
	}
	for _, kept := range []string{"go/constants.gen.go", "go/frontend_dist/notes.txt"} {
		if _, err := os.Stat(kept); err != nil {
			t.Errorf("%s was removed: %v", kept, err)
		}
	}
}
